-- Generated by scripts/build-setup-sql.mjs from drizzle/. Do not edit by hand.
-- Paste into Supabase → SQL Editor and run once on an empty database.
-- The editor runs the whole script as one transaction, so a failure leaves nothing half-made.
-- (No explicit BEGIN/COMMIT: after an error, those would leave the editor's connection holding locks.)

-- 0000_init
CREATE TABLE "documents" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"name" text NOT NULL,
	"type" text NOT NULL,
	"content_type" text NOT NULL,
	"size_in_bytes" integer NOT NULL,
	"storage_key" text NOT NULL,
	"uploaded_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "documents_storage_key_unique" UNIQUE("storage_key")
);
CREATE TABLE "visitor_queries" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"question" text NOT NULL,
	"visitor_name" text,
	"visitor_email" text,
	"context" text,
	"status" text DEFAULT 'open' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"resolved_at" timestamp with time zone
);

-- 0001_lock_down_tables
-- Supabase publishes tables in the public schema through its REST API. Turning on row-level
-- security with no policies blocks that API, while the site's own database connection is unaffected.
ALTER TABLE "documents" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "visitor_queries" ENABLE ROW LEVEL SECURITY;

-- 0002_chat_content_security
CREATE TABLE "admin_login_attempts" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"ip_hash" text NOT NULL,
	"succeeded" boolean NOT NULL,
	"attempted_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE "chat_conversations" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"ip_hash" text NOT NULL,
	"started_at" timestamp with time zone DEFAULT now() NOT NULL,
	"last_message_at" timestamp with time zone DEFAULT now() NOT NULL,
	"message_count" integer DEFAULT 0 NOT NULL
);
CREATE TABLE "chat_messages" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"conversation_id" uuid NOT NULL,
	"role" text NOT NULL,
	"content" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);
CREATE TABLE "site_content" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"status" text DEFAULT 'draft' NOT NULL,
	"content" jsonb NOT NULL,
	"summary" text,
	"source_document_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"published_at" timestamp with time zone
);
ALTER TABLE "documents" ADD COLUMN "extracted_text" text;
ALTER TABLE "documents" ADD COLUMN "use_in_chat" boolean DEFAULT false NOT NULL;
ALTER TABLE "documents" ADD COLUMN "sensitive_findings" jsonb DEFAULT '[]'::jsonb NOT NULL;
ALTER TABLE "chat_messages" ADD CONSTRAINT "chat_messages_conversation_id_chat_conversations_id_fk" FOREIGN KEY ("conversation_id") REFERENCES "public"."chat_conversations"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "site_content" ADD CONSTRAINT "site_content_source_document_id_documents_id_fk" FOREIGN KEY ("source_document_id") REFERENCES "public"."documents"("id") ON DELETE set null ON UPDATE no action;
CREATE INDEX "admin_login_attempts_ip_idx" ON "admin_login_attempts" USING btree ("ip_hash","attempted_at");
CREATE INDEX "chat_conversations_ip_idx" ON "chat_conversations" USING btree ("ip_hash","last_message_at");
CREATE INDEX "chat_messages_conversation_idx" ON "chat_messages" USING btree ("conversation_id","created_at");

-- 0003_lock_down_new_tables
-- Same as 0001: block Supabase's public REST API from the new tables.
ALTER TABLE "site_content" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "chat_conversations" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "chat_messages" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "admin_login_attempts" ENABLE ROW LEVEL SECURITY;

